INSERT INTO `listings` (`listing_id`, `seller_id`, `category_id`, `listing_type`, `title`, `description`, `price`, `quantity_available`, `listing_status`, `created_at`, `updated_at`) VALUES
	(1, 3, 1, 'Service', 'Professional Photography - Events & Portraits', 'Professional photography services for weddings, corporate events, birthdays, and portrait sessions. High-quality equipment, creative lighting, and expert editing. Packages include digital files and prints. Portfolio available upon request. Competitive rates.', 50.00, 1, 'Active', '2026-10-16 11:25:00', '2026-10-17 05:54:25'),
	(2, 3, 7, 'Product', 'Apple Watch Series 8 - 45mm GPS', 'Apple Watch Series 8 in excellent condition, 45mm case size with GPS. Features heart rate monitoring, ECG, blood oxygen sensor, always-on retina display, and crash detection. Includes sport band and magnetic charging cable. Battery health 95%.', 377.10, 27, 'Active', '2026-10-16 11:25:00', '2026-10-16 11:25:00'),
	(3, 3, 8, 'Product', 'Levi\'s 501 Original Fit Jeans - Size 32', 'Classic Levi\'s 501 Original Fit jeans in dark blue wash. Size 32 waist, 32 length. 100% cotton, button fly, straight leg. Authentic Levi\'s quality and style. Never worn, tags still attached. Perfect for casual wear.', 68.02, 42, 'Active', '2026-10-16 11:25:00', '2026-10-16 11:25:00'),
	(4, 3, 9, 'Product', 'Apple Watch Series 8 - 45mm GPS', 'Apple Watch Series 8 in excellent condition, 45mm case size with GPS. Features heart rate monitoring, ECG, blood oxygen sensor, always-on retina display, and crash detection. Includes sport band and magnetic charging cable. Battery health 95%.', 418.43, 32, 'Active', '2026-10-16 11:25:00', '2026-10-16 11:25:00'),
	(5, 3, 10, 'Product', 'IKEA Hemnes Bookshelf - White', 'IKEA Hemnes bookshelf in white, solid wood construction. 6 adjustable shelves, perfect for books, decor, or storage. Minimal assembly required. Excellent condition, no scratches or damage. Dimensions: 90x197x19 cm.', 80.22, 6, 'Active', '2026-10-16 11:25:00', '2026-10-16 11:25:00'),
	(6, 3, 11, 'Product', 'IKEA Hemnes Bookshelf - White', 'IKEA Hemnes bookshelf in white, solid wood construction. 6 adjustable shelves, perfect for books, decor, or storage. Minimal assembly required. Excellent condition, no scratches or damage. Dimensions: 90x197x19 cm.', 96.83, 24, 'Active', '2026-10-16 11:25:00', '2026-10-16 11:25:00'),
	(7, 3, 12, 'Product', 'Bosch Cordless Drill 18V - Professional Grade', 'Bosch 18V cordless drill/driver, professional grade. 2-speed gearbox, LED work light, 20+1 clutch settings. Includes 2 batteries, charger, and carrying case. Perfect for DIY projects and home repairs. Used lightly, excellent condition.', 194.33, 11, 'Active', '2026-10-16 11:25:00', '2026-10-16 11:25:00'),
	(8, 3, 13, 'Product', 'Levi\'s 501 Original Fit Jeans - Size 32', 'Classic Levi\'s 501 Original Fit jeans in dark blue wash. Size 32 waist, 32 length. 100% cotton, button fly, straight leg. Authentic Levi\'s quality and style. Never worn, tags still attached. Perfect for casual wear.', 86.65, 44, 'Active', '2026-10-16 11:25:00', '2026-10-16 11:25:00'),
	(9, 3, 14, 'Service', 'Plumbing Services - Repairs & Installations', 'Licensed plumber providing residential and commercial plumbing services. Leak detection, pipe repairs, fixture installation, water heater maintenance, and drain cleaning. Emergency services available. Fair pricing with no hidden fees. Fully insured.', 119.89, 1, 'Active', '2026-10-16 11:25:00', '2026-10-16 11:25:00'),
	(10, 3, 15, 'Service', 'Personal Training Sessions - Fitness Coach', 'Certified personal trainer offering one-on-one fitness coaching. Customized workout plans, nutrition guidance, and progress tracking. Sessions available at gym or your home. Specializes in weight loss, muscle building, and overall fitness. Flexible scheduling.', 50.22, 1, 'Active', '2026-10-16 11:25:01', '2026-10-16 11:25:01'),
	(11, 3, 16, 'Product', 'Herman Miller Aeron Chair - Size B', 'Authentic Herman Miller Aeron ergonomic office chair, size B. Fully adjustable with lumbar support, tilt mechanism, and armrests. Classic black color. Excellent condition, minimal wear. Perfect for home office or professional use.', 798.23, 35, 'Active', '2026-10-16 11:25:01', '2026-10-16 11:25:01'),
